-- Registries (certificate_registry, meeting_registry) are intentionally NOT under RLS: they are
-- read before any tenant context exists (public verification, Zoom webhooks) and hold only
-- non-sensitive pointers. The records they point to remain RLS-protected.

-- RLS on the new tenant-owned tables (same policy as 20261022000001_enable_rls).
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['lesson_progress', 'classroom_attendance']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I
         USING (tenant_id = app_current_tenant_id())
         WITH CHECK (tenant_id = app_current_tenant_id())',
      t
    );
  END LOOP;
END
$$;

-- Certificate codes are short and human-typed: keep them in one canonical form.
ALTER TABLE "certificate_registry" ADD CONSTRAINT "certificate_registry_code_format" CHECK ("code" ~ '^[A-Z0-9-]{8,32}$');
